    inventory = eb.ratchet_baseline_inventory(ROOT); files = {entry['file'] for entry in inventory}; known_ratchets = {'common/testing/data/protection-floor.json', 'common/meta/data/ac-tier-baseline.json', 'docs/project/traceability-exceptions.md'}; assert known_ratchets <= files
    for entry in inventory: assert isinstance(entry['entry_count'], int), entry; assert entry['last_shrink'], entry
